(window.__quranSurahs=window.__quranSurahs||{})[90]={"nomPhon":"Al-Balad","versets":{"1":{"text":"Non!... Je jure par cette Cité!","arabe":"لَآ أُقْسِمُ بِهَٰذَا ٱلْبَلَدِ"},"2":{"text":"et toi, tu es un résident dans cette cité -","arabe":"وَأَنتَ حِلٌّۢ بِهَٰذَا ٱلْبَلَدِ"},"3":{"text":"Et par le père et ce qu'il engendre!","arabe":"وَوَالِدٍۢ وَمَا وَلَدَ"},"4":{"text":"Nous avons, certes, créé l'homme pour une vie de lutte.","arabe":"لَقَدْ خَلَقْنَا ٱلْإِنسَٰنَ فِى كَبَدٍ"},"5":{"text":"Pense-t-il que personne ne pourra rien contre lui?","arabe":"أَيَحْسَبُ أَن لَّن يَقْدِرَ عَلَيْهِ أَحَدٌۭ"},"6":{"text":"Il dit: «J'ai gaspillé beaucoup de biens».","arabe":"يَقُولُ أَهْلَكْتُ مَالًۭا لُّبَدًا"},"7":{"text":"Pense-t-il que nul ne l'a vu?","arabe":"أَيَحْسَبُ أَن لَّمْ يَرَهُۥٓ أَحَدٌ"},"8":{"text":"Ne lui avons Nous pas assigné deux yeux,","arabe":"أَلَمْ نَجْعَل لَّهُۥ عَيْنَيْنِ"},"9":{"text":"et une langue et deux lèvres?","arabe":"وَلِسَانًۭا وَشَفَتَيْنِ"},"10":{"text":"Ne l'avons-Nous pas guidé aux deux voies.","arabe":"وَهَدَيْنَٰهُ ٱلنَّجْدَيْنِ"},"11":{"text":"Or, il ne s'engage pas dans la voie difficile!","arabe":"فَلَا ٱقْتَحَمَ ٱلْعَقَبَةَ"},"12":{"text":"Et qui te dira ce qu'est la voie difficile?","arabe":"وَمَآ أَدْرَىٰكَ مَا ٱلْعَقَبَةُ"},"13":{"text":"C'est délier un joug [affranchir un esclave],","arabe":"فَكُّ رَقَبَةٍ"},"14":{"text":"ou nourrir, en un jour de famine,","arabe":"أَوْ إِطْعَٰمٌۭ فِى يَوْمٍۢ ذِى مَسْغَبَةٍۢ"},"15":{"text":"un orphelin proche parent","arabe":"يَتِيمًۭا ذَا مَقْرَبَةٍ"},"16":{"text":"ou un pauvre dans le dénuement.","arabe":"أَوْ مِسْكِينًۭا ذَا مَتْرَبَةٍۢ"},"17":{"text":"Et c'est être, en outre, de ceux qui croient et s'enjoignent mutuellement l'endurance, et s'enjoignent mutuellement la miséricorde.","arabe":"ثُمَّ كَانَ مِنَ ٱلَّذِينَ ءَامَنُوا۟ وَتَوَاصَوْا۟ بِٱلصَّبْرِ وَتَوَاصَوْا۟ بِٱلْمَرْحَمَةِ"},"18":{"text":"Ceux-là sont les gens de la droite;","arabe":"أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْمَيْمَنَةِ"},"19":{"text":"alors que ceux qui ne croient pas en Nos versets sont les gens de la gauche.","arabe":"وَٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِنَا هُمْ أَصْحَٰبُ ٱلْمَشْـَٔمَةِ"},"20":{"text":"Le Feu se refermera sur eux.","arabe":"عَلَيْهِمْ نَارٌۭ مُّؤْصَدَةٌۢ"}}};